#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int alive = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    if ((di != 0 || dj != 0) && i + di >= 0 && i + di < n && j + dj >= 0 && j + dj < m) {
                        alive += g[i + di][j + dj];
                    }
                }
            }
            int next = g[i][j] == 1 ? (alive == 2 || alive == 3) : (alive == 3);
            cout << next << (j + 1 < m ? " " : "\n");
        }
    }

    return 0;
}

